// The built-in table of basic foods: fresh produce, raw meat and fish, and a
// few staples, with calories and macros per 100 g and typical weights, for
// products without a label. Generated by scripts/basic-foods.mjs from USDA
// FoodData Central (public domain).

import data from './basicFoods.json';
import { normalizeName } from './ingredients';
import { wordMatch } from './matching';
import { hasNutrition } from './nutrition';
import type { Nutrition, Product } from './types';

export interface BasicFood {
  name: string;
  aliases: string[];
  /** The USDA entry the values come from. */
  usda: string;
  fdcId: number;
  kcal: number;
  protein: number;
  fat: number;
  /** Without fibre, as on EU labels. */
  carbs: number;
  /** Grams in one of a recipe unit, as in Product.weights. */
  weights?: Record<string, number>;
}

export const basicFoods = data.foods as BasicFood[];
export const basicFoodsSource: string = data.source;

const keyed = basicFoods.map((food) => ({
  food,
  keys: [...new Set([food.name, ...food.aliases].map(normalizeName))],
}));

/**
 * The food a product most likely is, from its name. An exact name or alias
 * wins; otherwise a name the product's name contains as its main words, as
 * "Irish brown onions" for Onion, with the longest such name preferred.
 */
export function suggestBasicFood(productName: string): BasicFood | undefined {
  const name = normalizeName(productName);
  if (!name) return undefined;
  let best: { food: BasicFood; words: number } | undefined;
  for (const { food, keys } of keyed) {
    for (const key of keys) {
      if (key === name) return food;
      const words = key.split(' ').length;
      if (wordMatch(key, name) && (!best || words > best.words)) best = { food, words };
    }
  }
  return best?.food;
}

/** Foods whose name or alias contains the search, by name. */
export function searchBasicFoods(query: string): BasicFood[] {
  const typed = normalizeName(query);
  return keyed
    .filter(
      ({ food, keys }) =>
        !typed || keys.some((k) => k.includes(typed)) || normalizeName(food.name).includes(typed),
    )
    .map(({ food }) => food)
    .sort((a, b) => a.name.localeCompare(b.name));
}

export function foodNutrition(food: BasicFood): Required<Nutrition> {
  return { kcal: food.kcal, protein: food.protein, fat: food.fat, carbs: food.carbs };
}

export interface FoodFill {
  /** Set when the product had no complete nutrition. */
  nutrition?: Required<Nutrition>;
  /** Weights the product didn't have yet. */
  weights: Record<string, number>;
}

/**
 * What a food would add to a product: its nutrition, unless the product
 * already has all four values, and the weights the product doesn't have.
 * The product's own values are never replaced.
 */
export function fillFrom(
  food: BasicFood,
  product: Pick<Product, 'nutrition' | 'weights'>,
): FoodFill {
  const weights: Record<string, number> = {};
  for (const [key, grams] of Object.entries(food.weights ?? {}))
    if (!product.weights?.[key]) weights[key] = grams;
  return {
    nutrition: hasNutrition(product.nutrition) ? undefined : foodNutrition(food),
    weights,
  };
}

export function isEmptyFill(fill: FoodFill): boolean {
  return !fill.nutrition && !Object.keys(fill.weights).length;
}

/** The product with a fill applied. */
export function applyFill<T extends Pick<Product, 'nutrition' | 'nutritionPer' | 'weights'>>(
  product: T,
  fill: FoodFill,
): T {
  const weights = { ...product.weights, ...fill.weights };
  return {
    ...product,
    nutrition: fill.nutrition ?? product.nutrition,
    // The table's values are per 100 g.
    nutritionPer: fill.nutrition ? undefined : product.nutritionPer,
    weights: Object.keys(weights).length ? weights : undefined,
  };
}
